export const catalog = defaultCatalog;

export const publicTask = task => JSON.parse(JSON.stringify(task, (key, value) => key === 'c' ? undefined : value));
export const findTrack = id => catalog.find(t => t.id === id);
function combineTestTasks(tasks, id) {
  let start = 0;
  const subjectSections = tasks.map(task => {
    const section = { id: task.id, title: task.title, start, count: task.questions.length };
    start += task.questions.length;
    return section;
  });
  return {
    id,
    title: `Общий тест: ${tasks.map(task => task.title).join(' + ')}`,
    description: `Разделов: ${tasks.length} · вопросов: ${start}. Один общий тест с результатом по каждому разделу.`,
    type: 'test',
    subjectSections,
    questions: tasks.flatMap(task => task.questions.map(question => ({ ...question, q: `[${task.title}] ${question.q}` }))),
  };
}
export const combineSubjectTasks = tasks => combineTestTasks(tasks, 'combined-subject-test');
export const combineModelingTasks = tasks => combineTestTasks(tasks, 'combined-3d-test');
export function score(room, participant) {
  let correct = 0, total = 0;
  const englishBlocks = [0, 0, 0];
  for (const task of room.tasks) for (const [i, q] of (task.questions || []).entries()) {
    total++;
    if (participant.answers[task.id]?.choices?.[i] === q.c) {
      correct++;
      if (room.trackId === 'english' && i < 30) englishBlocks[Math.floor(i / 10)]++;
    }
  }
  const result = { correct, total, practicePending: room.tasks.some(t => t.practice) && !participant.grade };
  if (room.trackId === 'english' && room.tasks.length === 1 && room.tasks[0].questions?.length === 30) {
    const [basic, intermediate, advanced] = englishBlocks;
    result.englishLevel = basic >= 7 && intermediate >= 6 && advanced >= 6 ? 'B2'
      : basic >= 7 && intermediate >= 6 ? 'B1'
        : basic >= 7 ? 'A2'
          : basic >= 4 ? 'A1' : 'Ниже A1';
    result.englishBlocks = { a1a2: basic, b1: intermediate, b2: advanced };
  }
  if (['subject-disciplines', '3d-modeling'].includes(room.trackId) || (room.trackId === 'graphic-design' && (room.tasks.length > 1 || room.tasks[0]?.subjectSections))) {
    if (room.trackId !== 'subject-disciplines') result.subjectLabel = 'РЕЗУЛЬТАТ ПО РАЗДЕЛАМ';
    result.subjects = room.tasks.filter(task => task.questions).flatMap(task => {
      const sections = task.subjectSections || [{ id: task.id, title: task.title, start: 0, count: task.questions.length }];
      return sections.map(section => ({
        id: section.id,
        title: section.title,
        correct: task.questions.slice(section.start, section.start + section.count).reduce((count, question, index) => count + (participant.answers[task.id]?.choices?.[section.start + index] === question.c ? 1 : 0), 0),
        total: section.count,
      }));
    });
  }
  return result;
}
